/**
 * Embedded offline Telugu fonts for PDF generation.
 * 100% offline, zero network, zero asset loader dependencies.
 */

const NOTO_TELUGU_REGULAR_BASE64 = "";

const NOTO_TELUGU_BOLD_BASE64 = "";

export function getPdfFontCss(): string {
  return (
    "@font-face {" +
    "  font-family: 'NotoTelugu';" +
    "  font-weight: 400;" +
    "  src: url(data:font/ttf;base64," + NOTO_TELUGU_REGULAR_BASE64 + ") format('truetype');" +
    "}" +
    "@font-face {" +
    "  font-family: 'NotoTelugu';" +
    "  font-weight: 700;" +
    "  src: url(data:font/ttf;base64," + NOTO_TELUGU_BOLD_BASE64 + ") format('truetype');" +
    "}"
  );
}
